    q: "6. CR39 鏡片黃光折射率為1.5、藍光折射率為1.50460、紅光折射率為1.49598，鏡片屈光度為+10.00D，於鏡片中心上方1.2mm處產生之橫向色像差(lateral chromatic aberration)為何？",
    opts: ["2 稜鏡度", "1.2 稜鏡度", "0.2 稜鏡度", "0.02 稜鏡度"],
    ans: ["D"],
