    explain: "【盲點診斷】：<br>1. 先算阿貝數 V = (nd - 1) / (nF - nC) = (1.5 - 1) / (1.50460 - 1.49598) = 0.5 / 0.00862 ≈ 58。<br>2. 鏡片中心上方 1.2 mm (0.12 cm) 的稜鏡效應 P = c × F = 0.12 × 10 = 1.2 Δ。<br>3. 橫向色像差 TCA = P / V = 1.2 / 58 ≈ 0.02 稜鏡度，故選 D。"
