    explain: "【盲點診斷】：垂直入射表面反射率公式 R = [(n - 1)/(n + 1)]²。<br>• 折射率 n 越小，反射率 R 就越低。<br>• 而光在介質中的速度 v = c / n，折射率 n 越小，速度就「越快」！因此反射率最低的 4% 透鏡代表折射率最小、光速最快。"
