    q: "1. 配戴硬式隱形眼鏡(RGP)時，角膜平坦子午線曲率為 43.00D，若選用基弧為 43.50D 的鏡片配戴，則角膜與鏡片間所形成的淚液透鏡(Tear lens)屈光力為：",
